// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/account/login-logs", wrapper.ListCurrentUserLoginLogs)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/account/password", wrapper.ChangeCurrentUserPassword)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/auth/account/profile", wrapper.UpdateCurrentUserProfile)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/captcha", wrapper.CreateCaptcha)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/login-logs", wrapper.ListLoginLogs)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/me", wrapper.GetCurrentUser)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/auth/me/avatar-svg", wrapper.SetCurrentUserAvatarSVG)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/operation-logs", wrapper.ListOperationLogs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/users", wrapper.ListUsers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/users", wrapper.CreateUser)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/auth/users/{id}/contact", wrapper.UpdateUserContact)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/users/{id}/project-team-scopes", wrapper.ListUserProjectTeamScopes)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/auth/users/{id}/project-team-scopes", wrapper.ReplaceUserProjectTeamScopes)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/users/{id}/reset-password", wrapper.ResetUserPassword)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/auth/users/{id}/status", wrapper.UpdateUserStatus)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/auth/users/{id}/tenant-membership", wrapper.DeleteUserTenantMembership)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/users/{id}/tenant-membership", wrapper.GetUserTenantMembership)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/auth/users/{id}/tenant-membership", wrapper.UpsertUserTenantMembership)
	})

	return r
}
